{"content": "#!/usr/bin/env python3
"""Merge per-lane teacher-run outputs into data/mass_teacher/, re-id, validate.

Usage: python3 scripts/merge_outputs.py <raw_dir> <out_dir>
Lane dir names encode domain, e.g. cuda_kernel-rmsnorm, cuda2triton-shard0,
rtl-spec-shard1, rtl-explain-shard2. Files inside are *.jsonl (sft/rl).
"""
from __future__ import annotations

import json
import sys
from collections import defaultdict
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))
from pipelines.common import schema  # noqa: E402

LANE_TO_DOMAIN = {
    "cuda_kernel": "cuda_kernel",
    "cuda2triton": "kernel_translate",
    "cuda2sycl": "kernel_translate",
    "rtl-spec": "rtl",
    "rtl-explain": "rtl",
}


def lane_key(name: str) -> str:
    for prefix in sorted(LANE_TO_DOMAIN, key=len, reverse=True):
        if name.startswith(prefix):
            return prefix
    return name


def main() -> None:
    raw, out_dir = Path(sys.argv[1]), Path(sys.argv[2])
    out_dir.mkdir(parents=True, exist_ok=True)
    buckets: dict[tuple[str, str], list[dict]] = defaultdict(list)
    for lane in sorted(raw.iterdir()):
        if not lane.is_dir():
            continue
        domain = LANE_TO_DOMAIN.get(lane_key(lane.name), lane.name)
        for f in lane.glob("*.jsonl"):
            kind = "rl" if f.stem.endswith("_rl") or "_rl" in f.stem else "sft"
            for line in f.read_text().splitlines():
                if line.strip():
                    buckets[(domain, kind)].append(json.loads(line))

    summary = {}
    counters: dict[str, int] = defaultdict(int)
    for (domain, kind), rows in sorted(buckets.items()):
        path = out_dir / f"{domain}_{kind}.jsonl"
        with open(path, "a", encoding="utf-8") as fh:
            for r in rows:
                counters[domain] += 1
                r["id"] = f"{domain}-t{counters[domain]:05d}"
                fh.write(json.dumps(r, ensure_ascii=False) + "\n")
        errs = schema.validate_file(path, kind)
        summary[f"{domain}_{kind}"] = {"rows": len(rows), "schema_errors": len(errs)}
        for e in errs[:5]:
            print(f"[schema ERROR] {path.name}: {e}", file=sys.stderr)
    print(json.dumps(summary, indent=2))


if __name__ == "__main__":
    main()
", "path": "/home/hshen/posttrain_v4flash/scripts/merge_outputs.py"}

