             expected_stdout: str = "PASSED") -> dict:
    """Compile the self-test with a SYCL toolchain and run it.

    Pass criterion: exit code 0 AND `expected_stdout` in the program output
    (our translation contract requires main() to print a PASSED marker).
    Returns {"level": "L1", "passed": bool|None, "status": str, "log": str};
    passed is None with status "sycl_toolchain_missing" when no toolchain
    is installed (mirrors rtl/verify.py's iverilog_missing handling).

    If SYCL_REMOTE_HOST is set, verification is delegated to the remote
    oneAPI+XPU box via sycl_remote (takes precedence over local toolchain).
    """
    try:
        from pipelines.kernel_translate import sycl_remote
    except ImportError:
        try:
            from kernel_translate import sycl_remote  # type: ignore
        except ImportError:
            import importlib.util as _ilu
            _spec = _ilu.spec_from_file_location(
                "sycl_remote", Path(__file__).with_name("sycl_remote.py"))
            sycl_remote = _ilu.module_from_spec(_spec)  # type: ignore
            _spec.loader.exec_module(sycl_remote)  # type: ignore
    if sycl_remote.enabled():
        r = sycl_remote.verify_remote(src, work_id=f"l1-{hash(src) & 0xFFFFFFFF:08x}",
                                      compile_timeout=timeout)
        if r["passed"]:
