template <typename scalar_t>
struct SoftshrinkFunctor {
  scalar_t operator()(scalar_t a) const {
    return at::_isnan(a)
        ? a
        : (a > lambd_ ? a - lambd_ : (a < -lambd_ ? a + lambd_ : scalar_t(0)));
  }

  SoftshrinkFunctor(scalar_t lambd) : lambd_(lambd) {}

 private:
  scalar_t lambd_;
};

