"""统计 Nemotron-RL-Ultra-Training-Blends 7 个 blend 的成分构成。

用法: python3 blend_stats.py [blend_dir]
输出: 每个 blend 的行数、字段 schema、任务/verifier 类型分布、来源分布、长度分布。
"""
import json
import sys
from collections import Counter
from pathlib import Path

BLEND_DIR = Path(sys.argv[1]) if len(sys.argv) > 1 else Path(
    "/home/hshen/posttrain_v4flash/data/downloads/Nemotron-RL-Ultra-Training-Blends"
)
BLENDS = ["rlvr1", "rlvr2", "reasoning", "ifbench", "rlhf", "swe", "mopd"]


def prompt_len(row):
    """估算 prompt 字符数(兼容 messages / prompt 两种 schema)。"""
    msgs = row.get("messages") or row.get("prompt") or []
    if isinstance(msgs, str):
        return len(msgs)
    return sum(len(str(m.get("content", ""))) for m in msgs if isinstance(m, dict))


def analyze(path: Path):
    n = 0
    keys = Counter()
    # 常见区分维度,按出现情况统计
    dims = {k: Counter() for k in (
        "task_name", "task", "dataset", "source", "data_source",
        "verifier", "verifier_type", "reward_model", "env_name", "agent_name",
    )}
    lens = []
    with open(path) as f:
        for line in f:
            if not line.strip():
                continue
            row = json.loads(line)
            n += 1
            keys.update(row.keys())
            for k in dims:
                v = row.get(k)
                if v is not None:
                    dims[k][str(v)[:80]] += 1
            if n <= 200000:  # 长度统计全量做,内存可控(每行一个 int)
                lens.append(prompt_len(row))
    lens.sort()
    print(f"\n{'='*70}\n## {path.name}: {n} 行")
    print(f"字段: {sorted(keys.keys())}")
    for k, c in dims.items():
        if c:
            top = ", ".join(f"{v}×{cnt}" for v, cnt in c.most_common(12))
            print(f"  [{k}] ({len(c)} 类): {top}")
    if lens:
        def pct(p):
            return lens[min(len(lens) - 1, int(len(lens) * p))]
        print(f"  prompt 字符数: p50={pct(0.5)} p90={pct(0.9)} p99={pct(0.99)} max={lens[-1]}")


def main():
    for name in BLENDS:
        p = BLEND_DIR / f"{name}.jsonl"
        if p.exists():
            analyze(p)
        else:
            print(f"\n## {name}.jsonl: 缺失!")


if __name__ == "__main__":
    main()
"}

