def load_candidate_rows(
    path: Path,
    limit: int | None,
    stratified_limit: int | None,
    seed: int,
):
    """读取 prepare_phase_a_data.py 的紧凑候选文件，可按 agent/pass_rate 分层抽样。"""
    rows = []
    groups = defaultdict(list)
    with open(path) as f:
        for line in f:
            d = json.loads(line)
            row = {
                "responses_create_params": {
                    "input": [{"role": "user", "content": d["input"]}]
                },
                "expected_answer": d["output"],
                "agent_ref": {"name": d["agent_name"]},
                "uuid": d.get("uuid"),
                "pass_rate": d.get("pass_rate_nemotron"),
                "_candidate": d,
            }
            if stratified_limit:
                groups[(d["agent_name"], d.get("pass_rate_nemotron"))].append(row)
            else:
                rows.append(row)
                if limit and len(rows) >= limit:
                    break

    if not stratified_limit:
        return rows

    rng = random.Random(seed)
    for group in groups.values():
        rng.shuffle(group)
    keys = sorted(groups, key=lambda x: (x[0], float(x[1] or 0)))
    selected = []
    while len(selected) < stratified_limit:
        progressed = False
        for key in keys:
            if groups[key]:
                selected.append(groups[key].pop())
                progressed = True
                if len(selected) == stratified_limit:
                    break
        if not progressed:
            break
    rng.shuffle(selected)
    return selected


def build_prompt(row, thinking_mode: str) -> str:
    msgs = row["responses_create_params"]["input"]
    agent = row["agent_ref"]["name"]
    clean = [
        {
            "role": m.get("role", "user"),
            "content": (
                format_prompt_for_verifier(agent, m.get("content", ""))
                if m.get("role") == "user"
                else m.get("content", "")
            ),
        }
        for m in msgs
        if m.get("role") in ("system", "user", "assistant")
    ]
    return encode_messages(clean, thinking_mode=thinking_mode)

